import { ChangeDetectionStrategy, Component, booleanAttribute, input } from '@angular/core';

@Component({
  selector: 'input[aevkoSlider][type="range"]',
  standalone: true,
  template: '',
  styleUrl: './slider.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '[attr.aria-invalid]': 'invalid() ? "true" : null',
    '[attr.data-orientation]': 'orientation()',
  },
})
export class AevkoSlider {
  readonly invalid = input(false, { transform: booleanAttribute });
  readonly orientation = input<'horizontal' | 'vertical'>('horizontal');
}

:host {
  appearance: none;
  background: transparent;
  cursor: pointer;
  height: 1.5rem;
  margin: 0;
  width: 100%;
}
:host::-webkit-slider-runnable-track {
  background: var(--aevko-surface-strong, #d4d4d8);
  height: 0.25rem;
}
:host::-moz-range-track {
  background: var(--aevko-surface-strong, #d4d4d8);
  height: 0.25rem;
}
:host::-webkit-slider-thumb {
  appearance: none;
  background: var(--aevko-foreground, #09090b);
  border: 0;
  border-radius: var(--aevko-radius, 0);
  height: 1rem;
  margin-top: -0.375rem;
  width: 1rem;
}
:host::-moz-range-thumb {
  background: var(--aevko-foreground, #09090b);
  border: 0;
  border-radius: var(--aevko-radius, 0);
  height: 1rem;
  width: 1rem;
}
:host:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 2px;
}
:host:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
:host([data-orientation='vertical']) {
  height: 10rem;
  width: 1.5rem;
  writing-mode: vertical-lr;
  direction: rtl;
}
